const f3 = (x) => x.toFixed(3);
const words = { 1: 'One', 3: 'Three', 4: 'Four', 9: 'nine' };

async function run(ctx) {
  const T = ctx.tree();
  const out = {};
  // 1. Regenerate the summary in the scratch export. wild-sheet.ts writes into results/v1.3-wild of its cwd; the three
  //    files are restored afterwards so other groups see the committed export.
  const files = ['summary.json', 'review-key.json', 'review-sheet.md'];
  const bak = ctx.out('d-wild-bak');
  for (const f of files) copyFileSync(join(T, W, f), join(bak, f));
  const empty = ctx.out('d-wild-noclones');
  ctx.sh(`node --import tsx scripts/v1.3/wild-sheet.ts --repos "${empty}"`, { cwd: T });
  const sum = JSON.parse(readFileSync(join(T, W, 'summary.json'), 'utf8'));
  const keyIdentical = readFileSync(join(T, W, 'review-key.json'), 'utf8') === ctx.read(`${W}/review-key.json`);
  const sumIdentical = readFileSync(join(T, W, 'summary.json'), 'utf8') === ctx.read(`${W}/summary.json`);
  for (const f of files) copyFileSync(join(bak, f), join(T, W, f));
  if (!sumIdentical || !keyIdentical) process.stderr.write(`   d-wild: regenerated summary.json identical=${sumIdentical}, review-key.json identical=${keyIdentical}\n`);
  const P = Object.fromEntries(sum.perRepo.map((r) => [r.id, r]));
  const sel = ctx.json(`${W}/selection.json`);

  // 2. jest: the wild unit tests.
  const jest = ctx.sh('npx jest --maxWorkers=2 --forceExit tests/unit/scripts/v1.3/wild.test.ts 2>&1', { cwd: T });
  out['d-wild-tests'] = (jest.match(/Tests:\s+(\d+) passed, (\d+) total/) ?? [])[2] ?? 'no tally';

  const N = sum.repos;
  out['d-wild-title-repos'] = String(N);
  out['d-wild-pool'] = String(sel.entries.length + sel.rejected.length);
  out['d-wild-resolved'] = String(sel.entries.length + sel.rejected.filter((r) => !/Study 1 corpus/.test(r.reason)).length);
  out['d-wild-kept'] = String(sel.entries.length);
  out['d-wild-rejected'] = String(sel.rejected.length);
  R.forEach((id) => { out[`d-wild-s1-files-${short(id)}`] = String(P[id].harness.sourceFiles); });
  const filesTotal = fmt(R.reduce((a, id) => a + P[id].harness.sourceFiles, 0));
  out['d-wild-files-total'] = filesTotal;
  out['d-wild-extends-unfollowed'] = words[R.reduce((a, id) => a + P[id].harness.notes.filter((x) => /not followed/.test(x)).length, 0)] ?? '?';
  out['d-wild-nine-templates'] = words[Object.keys(sum.totals.apg2).length] ?? String(Object.keys(sum.totals.apg2).length);

  // §3 fidelity. Cell = tsc refCoveredByApg / apgConfirmedByRef; the doc says depcruise gave the same file edges.
  const V = { v12e: 'apg-v12e-default', v13lit: 'apg-v13-literal', v13res: 'apg-v13-resolved' };
  let sameRefs = 0; let litExact = 0; let litDis = 0;
  for (const id of R) {
    const fd = P[id].fidelity;
    const ag = fd.agreement;
    out[`d-wild-s3-files-${short(id)}`] = String(fd.files.apg);
    out[`d-wild-s3-refedges-${short(id)}`] = String(ag['apg-v13-literal'].tsc.refEdges);
    for (const [k, v] of Object.entries(V)) {
      const a = ag[v].tsc;
      let cell = `${f3(a.refCoveredByApg)} / ${f3(a.apgConfirmedByRef)}`;
      const dyn = fd.classes[v].tsc['missing-in-apg:dynamic-import'] ?? 0;
      if (id === 'immich-server' && k === 'v12e') cell += ` (${dyn} dynamic import missed)`;
      out[`d-wild-s3-${k}-${short(id)}`] = cell;
    }
    if (Object.values(V).every((v) => ag[v].tsc.both === ag[v].depcruise.both && ag[v].tsc.refEdges === ag[v].depcruise.refEdges && ag[v].tsc.apgEdges === ag[v].depcruise.apgEdges)) sameRefs++;
    const L = ag['apg-v13-literal'];
    if (L.tsc.onlyApg + L.tsc.onlyRef + L.depcruise.onlyApg + L.depcruise.onlyRef === 0) litExact++;
    litDis += L.tsc.onlyApg + L.tsc.onlyRef + L.depcruise.onlyApg + L.depcruise.onlyRef;
  }
  if (sameRefs !== N) process.stderr.write(`   d-wild: tsc and depcruise scoped edges differ on ${N - sameRefs} repositories\n`);
  const cls = (v, ref, k, ids = R) => ids.reduce((a, id) => a + (P[id].fidelity.classes[v][ref][k] ?? 0), 0);
  out['d-wild-lit-repos'] = String(litExact);
  out['d-wild-lit-scoped-dis'] = String(litDis);
  out['d-wild-dc-excluded'] = fmt(cls('apg-v13-literal', 'depcruise', 'missing-in-apg:excluded-file'));
  const tscExcl = R.filter((id) => (P[id].fidelity.classes['apg-v13-literal'].tsc['missing-in-apg:excluded-file'] ?? 0) > 0);
  out['d-wild-tsc-excluded'] = tscExcl.sort().join(',') === 'etherpad,medplum-server,podkrepi-api' ? String(cls('apg-v13-literal', 'tsc', 'missing-in-apg:excluded-file')) : `in ${tscExcl.join(',')}`;
  // missing-in-ref = an edge only v1.2E has (resolved through the barrel); missing-in-apg = only the references have it (literal).
  out['d-wild-barrel-resolved-only'] = String(cls('apg-v12e-default', 'tsc', 'missing-in-ref:re-export/barrel'));
  out['d-wild-barrel-literal-only'] = String(cls('apg-v12e-default', 'tsc', 'missing-in-apg:re-export/barrel'));
  const ct = P['clean-ts-api'].fidelity.agreement['apg-v12e-default'].tsc;
  out['d-wild-cleants-short'] = `${ct.refCoveredByApg.toFixed(2)}/${ct.apgConfirmedByRef.toFixed(2)}`;
  const reqRepos = R.filter((id) => (P[id].fidelity.classes['apg-v12e-default'].tsc['missing-in-apg:require'] ?? 0) > 0);
  out['d-wild-require'] = reqRepos.join() === 'etherpad' ? String(cls('apg-v12e-default', 'tsc', 'missing-in-apg:require')) : `in ${reqRepos}`;
  out['d-wild-dyn-total'] = String(cls('apg-v12e-default', 'tsc', 'missing-in-apg:dynamic-import'));
  for (const id of ['awesome-nest-boilerplate', 'medplum-server', 'reactive-resume-api', 'etherpad', 'immich-server', 'clean-ts-api']) {
    out[`d-wild-dyn-${short(id)}`] = String(P[id].fidelity.classes['apg-v12e-default'].tsc['missing-in-apg:dynamic-import'] ?? 0);
  }
  const resMiss = ['tsc', 'depcruise'].reduce((a, ref) => a + cls('apg-v13-resolved', ref, 'missing-in-apg:require') + cls('apg-v13-resolved', ref, 'missing-in-apg:dynamic-import'), 0);
  out['d-wild-res-req-dyn'] = resMiss === 0 ? 'no require or dynamic-import misses' : `${resMiss} misses`;

  // §4 templates
  R.forEach((id) => TPL.forEach((t, j) => { out[`d-wild-s4-${TPL_SHORT[j]}-${short(id)}`] = String(P[id].apg2.counts[t] ?? 0); }));
  TPL.forEach((t, j) => { out[`d-wild-s4-total-${TPL_SHORT[j]}`] = fmt(sum.totals.apg2[t] ?? 0); });
  out['d-wild-obs-adp'] = String(sum.totals.apg2['component-adp-cycle']);
  out['d-wild-obs-sdp'] = String(sum.totals.apg2['component-sdp-violation']);
  const refs3 = ['clean-ts-api', 'domain-driven-hexagon', 'bitloops-ddd-backend'];
  const adp3 = Math.max(...refs3.map((id) => P[id].apg2.counts['component-adp-cycle']));
  const sdp3 = Math.max(...refs3.map((id) => P[id].apg2.counts['component-sdp-violation']));
  out['d-wild-obs-refs-adp-sdp'] = `${adp3} ADP rows and at most ${sdp3} SDP rows each`;
  out['d-wild-di-immich'] = String(P['immich-server'].apg2.counts['deep-import-inferred-api']);
  out['d-wild-di-medplum'] = String(P['medplum-server'].apg2.counts['deep-import-inferred-api']);
  out['d-wild-di-standardnotes'] = String(P['standardnotes-auth'].apg2.counts['deep-import-inferred-api']);
  const asyncRepos = R.filter((id) => P[id].apg2.counts['undeclared-async-coupling'] > 0);
  out['d-wild-async-rows'] = asyncRepos.join() === 'domain-driven-hexagon' ? String(sum.totals.apg2['undeclared-async-coupling']) : `in ${asyncRepos}`;
  const dn = (id) => P[id].apg2.stats.async.dynamicNames;
  out['d-wild-dyn-names'] = `immich ${dn('immich-server')}, medplum ${dn('medplum-server')}, hedgedoc ${dn('hedgedoc-backend')}`;

  // §5 cheap proxies
  R.forEach((id) => PRX.forEach((p) => { out[`d-wild-s5-${p}-${short(id)}`] = fmt(P[id].cheap.counts[p] ?? 0); }));
  PRX.forEach((p) => { out[`d-wild-s5-total-${p}`] = fmt(sum.totals.cheap[p] ?? 0); });
  for (const k of Object.keys(sum.totals.cheapKinds)) out[`d-wild-kind-${k.replace(/[/]/g, '-')}`] = fmt(sum.totals.cheapKinds[k]);
  const hk = P['hoppscotch-backend'].cheap.kinds;
  out['d-wild-hopp-near'] = fmt(hk['clones/cross-component-near']);
  const hc = ctx.json(`${W}/repos/hoppscotch-backend/cheap.json`);
  const flags = JSON.parse(gunzipSync(readFileSync(ctx.p(`${W}/repos/hoppscotch-backend/${hc.flagsFile}`))).toString('utf8'));
  const pair = flags.find((f) => f.proxy === 'clones' && f.evidence.file === 'src/user/user.resolver.ts' && f.evidence.startLine === 74
    && f.related?.file === 'src/access-token/access-token.controller.ts' && f.related.startLine === 43);
  out['d-wild-hopp-sim'] = pair ? `similarity ${pair.score.toFixed(2)}` : 'no such flag';
  out['d-wild-hopp-share'] = ctx.pct(P['hoppscotch-backend'].cheap.counts.clones / sum.totals.cheap.clones);
  out['d-wild-lit-number-share'] = `${fmt(sum.totals.cheapKinds['shared-literals/shared-number-literal'])} of ${fmt(sum.totals.cheap['shared-literals'])}`;
  let sigs = 0; let sites = 0;
  for (const id of R) { const s = ctx.json(`${W}/repos/${id}/cheap.json`).summaries['framework-in-core']; sigs += s.signaturesChecked; sites += s.sites; }
  out['d-wild-fic-sigs'] = fmt(sigs);
  out['d-wild-fic-repos'] = String(N);
  out['d-wild-fic-sites'] = String(sites);
  out['d-wild-communities'] = fmt(sum.totals.cheap.communities);

  // §6 ISE
  const nm = (s) => (s === 'clean-architecture' ? 'clean' : s);
  R.forEach((id) => {
    const ise = P[id].ise;
    let style = `${ise.style} (${ctx.f2(ise.confidence)})`;
    if (ise.runnerUp && ise.runnerUp.confidence === ise.confidence) style += `, tied with ${ise.runnerUp.style} (${ctx.f2(ise.runnerUp.confidence)})`;
    out[`d-wild-s6-style-${short(id)}`] = style;
    out[`d-wild-s6-runner-${short(id)}`] = id === 'etherpad' ? `${ise.runnerUp.style} (${ctx.f2(ise.runnerUp.confidence)})` : `${nm(ise.runnerUp.style)} (${ctx.f2(ise.runnerUp.confidence)})`;
    const ev = ise.evidence.join(' | ');
    for (const [k] of S6_EV[id] ?? []) {
      let v = '?';
      if (k === 'module') v = `${(ev.match(/(\d+) @Module classes/) ?? [])[1]} \`@Module\``;
      if (k === 'decorated') v = `${(ev.match(/(\d+\/\d+) classes carry NestJS decorators/) ?? [])[1]} decorated classes`;
      if (k === 'dotsuffix') v = `${(ev.match(/(\d+) files with NestJS dot suffixes/) ?? [])[1]} dot-suffix files`;
      if (k === 'chain') v = `${(ev.match(/a chain of (\d+) unit levels without dependency inversion/) ?? [])[1]}-level chain without inversion`;
      out[`d-wild-s6-ev-${k}-${short(id)}`] = v;
    }
  });
  out['d-wild-spec-valid'] = String(R.filter((id) => P[id].ise.specValid).length);
  out['d-wild-ether-tie'] = ctx.f2(P.etherpad.ise.confidence);
  out['d-wild-rr-conf'] = ctx.f2(P['reactive-resume-api'].ise.confidence);

  // §7 detections
  const inv = (id, t) => P[id].importGraphInvisible[t];
  out['d-wild-immich-btl-invisible'] = `${inv('immich-server', 'boundary-type-leak').invisible} of immich's ${inv('immich-server', 'boundary-type-leak').total}`;
  out['d-wild-medplum-btl-invisible'] = `${inv('medplum-server', 'boundary-type-leak').invisible} of medplum's ${inv('medplum-server', 'boundary-type-leak').total}`;
  const ddh = ctx.json(`${W}/repos/domain-driven-hexagon/apg2.json`).rows['undeclared-async-coupling'];
  const pubs = new Set(ddh.filter((r) => /create-user\.(http|cli|message)\.controller\.ts$/.test(r._file ?? '')).map((r) => r._file));
  out['d-wild-ddh-controllers'] = words[pubs.size] ?? String(pubs.size);
  const ndInv = R.reduce((a, id) => a + inv(id, 'nondeterminism-in-core').invisible, 0);
  out['d-wild-nd-invisible'] = `${ndInv} of ${sum.totals.apg2['nondeterminism-in-core']}`;
  const cp = R.reduce((a, id) => a + inv(id, 'cross-component clone/literal pairs').total, 0);
  const cpi = R.reduce((a, id) => a + inv(id, 'cross-component clone/literal pairs').invisible, 0);
  out['d-wild-clone-pairs'] = fmt(cp);
  out['d-wild-clone-pairs-invisible'] = `${fmt(cpi)} (${ctx.pct(cpi / cp)})`;
  const tx = ctx.json(`${W}/repos/ts-express-starter-prisma/apg2.json`).rows;
  const adp = tx['component-adp-cycle']; const sdp = tx['component-sdp-violation'];
  out['d-wild-tsx-adp-from-config'] = `${adp.filter((r) => r.component === 'config').length} of the repository's ${adp.length}`;
  out['d-wild-tsx-adp-to-config'] = `${adp.filter((r) => r.target === 'config').length} more`;
  out['d-wild-tsx-sdp-config'] = sdp.every((r) => r.component === 'config' || r.target === 'config') ? `all ${sdp.length}` : `${sdp.filter((r) => r.component === 'config' || r.target === 'config').length} of ${sdp.length}`;
  out['d-wild-tsx-sdp-config-folder'] = (words[sdp.filter((r) => r.component === 'config' && r.kind === 'folder').length] ?? '?').toLowerCase();

  // §8 cost, from the committed per-stage cost.json (analyse) and fidelity/<id>/cost.json
  let A = 0; let F = 0; let rss = 0; let frss = 0;
  R.forEach((id) => {
    const c = ctx.json(`${W}/repos/${id}/cost.json`); const fc = ctx.json(`${W}/fidelity/${id}/cost.json`);
    const w = c.wallMs; const tot = w.ise + w.extractApg2 + w.apg2Templates + w.cheap;
    A += tot; F += fc.wallMs; rss = Math.max(rss, c.peakRssMb); frss = Math.max(frss, fc.peakRssMb);
    const v = [String(c.files), (w.ise / 1000).toFixed(1), (w.extractApg2 / 1000).toFixed(1), (w.apg2Templates / 1000).toFixed(2),
      (w.cheap / 1000).toFixed(1), (tot / 1000).toFixed(1), String(c.peakRssMb), (fc.wallMs / 1000).toFixed(1), String(fc.peakRssMb)];
    S8_COLS.forEach((col, j) => { out[`d-wild-s8-${col}-${short(id)}`] = v[j]; });
  });
  out['d-wild-s8-files-total'] = filesTotal;
  out['d-wild-s8-analyse-total'] = (A / 1000).toFixed(1);
  out['d-wild-s8-analyse-rss-max'] = String(rss);
  out['d-wild-s8-fid-total'] = (F / 1000).toFixed(1);
  out['d-wild-s8-fid-rss-max'] = String(frss);
  out['d-wild-run-minutes'] = `about ${((A + F) / 60000).toFixed(1)} minutes`;
  const mc = ctx.json(`${W}/repos/medplum-server/cheap.json`).timingsMs;
  out['d-wild-medplum-cheap'] = `${(P['medplum-server'].cost.analyse.wallMs.cheap / 1000).toFixed(1)} s`;
  out['d-wild-medplum-literals'] = `${(mc['shared-literals'] / 1000).toFixed(1)} s`;
  out['d-wild-medplum-clones'] = `${(mc.clones / 1000).toFixed(1)} s`;
  out['d-wild-peak-gb'] = Math.max(rss, frss) < 850 ? 'under 0.85 GB' : `${Math.max(rss, frss)} MB`;

  // §9
  const ok = R.filter((id) => P[id].error === null && P[id].ise.specValid && P[id].fidelity.ok && P[id].cost.fidelity.exit === 0).length;
  out['d-wild-extracted'] = ok === N ? `All ${N}` : `${ok} of ${N}`;
  out['d-wild-async-dyn-sites'] = String(dn('immich-server') + dn('medplum-server') + dn('hedgedoc-backend'));
  out['d-wild-sel-14'] = String(N);
  out['d-wild-review-items'] = String(sum.review.items);
  out['d-wild-review-absent'] = words[Object.values(sum.review.poolSizes).filter((v) => v === 0).length] ?? '?';
  out['d-wild-review-async'] = String(sum.review.poolSizes['undeclared-async-coupling']);
  return out;
}

export default [{
  id: 'd-wild',
  title: 'Wild run: 14 public backends (fidelity, APG v2, cheap proxies, ISE, cost)',
  needs: 'offline',
  basis: 'regenerated',
  slow: false,
  how: 'node --import tsx scripts/v1.3/wild-sheet.ts --repos <empty dir> (in a scratch export; summary.json and review-key.json regenerate byte-identically) + committed wild-run.ts outputs + npx jest --maxWorkers=2 tests/unit/scripts/v1.3/wild.test.ts',
  numbers,
  run,
}];
